function dns(point: GraphKnowledgePoint) {
  const actors = [
    actor("browser", "浏览器 / Stub", "Browser / Stub", "本地缓存与系统解析入口", "Local cache and OS resolver entry", "client"),
    actor("recursive", "递归解析器", "Recursive Resolver", "缓存、递归查询与结果返回", "Cache, recursive lookup, and answer return", "server"),
    actor("root", "根 DNS", "Root DNS", "返回 TLD 名称服务器线索", "Returns a TLD nameserver referral", "network"),
    actor("tld", "TLD DNS", "TLD DNS", "返回域名权威服务器线索", "Returns an authoritative-server referral", "network"),
    actor("authority", "权威 DNS", "Authoritative DNS", "返回 A/AAAA/CNAME 记录", "Returns A / AAAA / CNAME records", "network"),
    actor("app", "目标服务", "Target Service", "接收后续 TCP/QUIC 连接", "Receives the later TCP / QUIC connection", "server"),
  ];

  return makeSimulation(
    "network",
    point,
    tx("递归解析路径", "recursive resolution path"),
    tx("模拟本地缓存、递归解析器、根/TLD/权威 DNS、TTL 缓存和过期后的重新查询。", "Simulate local cache, recursive resolver, root / TLD / authoritative DNS, TTL cache, and refresh after expiry."),
    actors,
    {
      browser: tx("需要 example.com 的 IP", "Needs the IP for example.com"),
      recursive: tx("检查 resolver cache", "Checking resolver cache"),
      root: tx("持有根区委派", "Has root-zone delegations"),
      tld: tx("持有 .com 区委派", "Has .com delegations"),
      authority: tx("持有 example.com 记录", "Has example.com records"),
      app: tx("等待后续连接", "Waiting for the later connection"),
    },
    [
      step(
        "缓存与递归入口",
        "Cache and recursive entry",
        "检查本地与 resolver 缓存",
        "Check local and resolver cache",
        "browser",
        "recursive",
        "QNAME example.com A/AAAA",
        "QNAME example.com A / AAAA",
        "浏览器和系统先查本地缓存，缓存过期或缺失时把查询交给递归解析器。",
        "The browser and OS check local cache first, then send the query to a recursive resolver after a miss or expiry.",
        "DNS 排障先区分本地缓存、递归解析器缓存和权威记录。",
        "DNS debugging starts by separating local cache, resolver cache, and authoritative records.",
        { browser: tx("缓存缺失，发出查询", "Cache miss, query sent"), recursive: tx("resolver cache miss", "resolver cache miss") },
      ),
      step(
        "根区委派",
        "Root referral",
        "查询根名称服务器",
        "Ask root nameserver",
        "recursive",
        "root",
        ". -> .com NS",
        ". -> .com NS",
        "递归解析器使用 root hints 查询根 DNS，根服务器返回负责 .com 的 TLD 名称服务器。",
        "The resolver uses root hints to query root DNS, and root returns the TLD nameservers for .com.",
        "根 DNS 返回下一跳线索，最终 IP 来自后续权威记录。",
        "Root DNS returns the next referral, and the final IP comes from a later authoritative record.",
        { recursive: tx("收到根区委派", "Root referral received"), root: tx("返回 .com NS", "Returned .com NS") },
        "teal",
      ),
      step(
        "TLD 委派",
        "TLD referral",
        "查询 .com TLD",
        "Ask .com TLD",
        "recursive",
        "tld",
        ".com -> ns.example.com",
        ".com -> ns.example.com",
        ".com TLD 根据域名返回 example.com 的权威名称服务器。",
        "The .com TLD returns the authoritative nameservers for example.com.",
        "TLD 层决定域名由哪组权威服务器回答。",
        "The TLD layer decides which authoritative servers answer for the domain.",
        { recursive: tx("收到权威 NS 线索", "Authoritative NS referral received"), tld: tx("返回 example.com NS", "Returned example.com NS") },
        "warning",
      ),
      step(
        "权威应答与 TTL",
        "Authoritative answer and TTL",
        "查询权威 DNS",
        "Ask authoritative DNS",
        "recursive",
        "authority",
        "A/AAAA + TTL",
        "A / AAAA + TTL",
        "权威 DNS 返回 A/AAAA 或 CNAME 链路，递归解析器按 TTL 写入缓存。",
        "Authoritative DNS returns A / AAAA records or a CNAME chain, and the resolver caches the answer using TTL.",
        "TTL 控制旧记录在缓存中的保留时间，也影响变更生效速度。",
        "TTL controls how long stale records can remain cached and how quickly changes take effect.",
        { recursive: tx("缓存 IP + TTL=300s", "Cached IP + TTL=300s"), authority: tx("返回 203.0.113.42", "Returned 203.0.113.42") },
        "success",
      ),
      step(
        "返回答案并连接",
        "Return answer and connect",
        "返回 IP 并连接服务",
        "Return IP and connect",
        "recursive",
        "app",
        "203.0.113.42 + TCP/QUIC",
        "203.0.113.42 + TCP / QUIC",
        "递归解析器把结果返回给客户端；后续访问使用解析出的 IP 建立 TCP、TLS 或 QUIC 连接。",
        "The recursive resolver returns the answer to the client, then the later request opens TCP, TLS, or QUIC to the resolved IP.",
        "DNS 问题常从慢查询、错误 IP、旧缓存和权威记录漂移四类证据定位。",
        "DNS issues are commonly diagnosed through slow lookup, wrong IP, stale cache, and authoritative-record drift.",
        { browser: tx("拿到 IP，开始连接", "IP resolved, connecting"), recursive: tx("缓存命中窗口开启", "Cache hit window opened"), app: tx("收到后续连接", "Later connection received") },
        "success",
      ),
    ],
    [
      tx("递归解析器", "recursive resolver"),
      tx("根区委派", "root referral"),
      tx("TLD 委派", "TLD referral"),
      tx("权威 A/AAAA", "authoritative A/AAAA"),
      tx("TTL 缓存", "TTL cache"),
    ],
  );
}

