function redisForkCow(point: GraphKnowledgePoint) {
  const actors = [
    actor("parent", "Redis 主进程", "Redis parent", "继续处理客户端写入", "Keeps serving client writes", "cache"),
    actor("child", "后台子进程", "Background child", "读取 fork 时刻的数据快照", "Reads the dataset snapshot at fork time", "cpu"),
    actor("pagetable", "页表快照", "Page table snapshot", "复制虚拟页映射和只读标记", "Copies virtual mappings and read-only marks", "data"),
    actor("pages", "物理内存页", "Physical memory pages", "父子进程初始共享页框", "Parent and child initially share page frames", "storage"),
    actor("cow", "COW 页复制", "COW page copy", "写入命中的页被复制给父进程", "Written pages are copied for the parent", "storage"),
    actor("writer", "RDB/AOF/Full Sync", "RDB / AOF / full sync", "子进程把快照写入磁盘或网络", "Child writes the snapshot to disk or network", "server"),
    actor("metrics", "排障指标", "Debug metrics", "latest_fork_usec、RSS、latency 事件", "latest_fork_usec, RSS, latency events", "security"),
  ];

  return makeSimulation(
    "redis",
    point,
    tx("fork/COW 内存状态模型", "fork/COW memory state model"),
    tx(
      "观察 Redis 后台任务如何 fork 子进程、共享物理页，并在主进程写入时通过 Copy-on-Write 复制脏页。",
      "Observe how Redis background jobs fork a child, share physical pages, and copy written pages through Copy-on-Write while the parent keeps writing.",
    ),
    actors,
    {
      parent: tx("事件循环处理写命令", "event loop serves writes"),
      child: tx("等待后台任务", "awaiting background job"),
      pagetable: tx("页表归属父进程", "page table owned by parent"),
      pages: tx("used_memory=24GB", "used_memory=24GB"),
      cow: tx("尚未复制页面", "no pages copied"),
      writer: tx("BGSAVE/BGREWRITEAOF 空闲", "BGSAVE/BGREWRITEAOF idle"),
      metrics: tx("latest_fork_usec=0", "latest_fork_usec=0"),
    },
    [
      step(
        "触发后台任务",
        "Trigger background job",
        "BGSAVE 或 BGREWRITEAOF 进入队列",
        "BGSAVE or BGREWRITEAOF enters the queue",
        "parent",
        "pagetable",
        "fork pending",
        "fork pending",
        "Redis 准备生成 RDB、重写 AOF 或执行全量同步，主进程先检查后台持久化任务状态。",
        "Redis prepares to create RDB, rewrite AOF, or run full synchronization, and the parent checks background persistence state first.",
        "入口排查关注 bgsave/aof_rewrite 是否已在运行，以及磁盘和内存余量。",
        "At entry, check whether bgsave or aof_rewrite is already running, plus disk and memory headroom.",
        {
          parent: tx("后台任务已接受", "background job accepted"),
          pagetable: tx("等待 fork 页表", "awaiting fork page table"),
          writer: tx("后台写入准备中", "background writer preparing"),
        },
      ),
      step(
        "fork 复制页表",
        "Fork copies page tables",
        "复制虚拟映射并标记共享页",
        "Copy virtual mappings and mark shared pages",
        "pagetable",
        "child",
        "latest_fork_usec",
        "latest_fork_usec",
        "fork 会复制父进程页表，父子进程映射到同一批物理页；数据页本体仍共享，页表复制成本随实例内存增长。",
        "fork copies the parent's page tables so parent and child map the same physical pages; data pages remain shared, while page-table cost grows with instance size.",
        "latest_fork_usec 反映 fork 阶段阻塞窗口，透明大页和大实例会放大这个读数。",
        "latest_fork_usec reflects the fork blocking window, and huge pages or large instances can amplify it.",
        {
          parent: tx("短暂停顿后继续服务", "brief pause then continues"),
          child: tx("拿到 fork 快照", "has fork snapshot"),
          pagetable: tx("页表副本 + 只读映射", "page-table copy + read-only maps"),
          pages: tx("父子共享 Page A/B/C", "parent and child share Page A/B/C"),
          metrics: tx("latest_fork_usec=18ms", "latest_fork_usec=18ms"),
        },
        "teal",
      ),
      step(
        "主进程继续写入",
        "Parent keeps writing",
        "写命令命中共享页",
        "Write command hits a shared page",
        "parent",
        "pages",
        "write fault",
        "write fault",
        "子进程写快照期间，主进程继续执行 SET、HSET 等写命令；如果写入命中共享页，内核触发写保护缺页。",
        "While the child writes the snapshot, the parent keeps executing writes such as SET or HSET; when a write hits a shared page, the kernel triggers a write-protection fault.",
        "COW 风险来自写入量和页覆盖范围，热 key 与大对象会让复制页数快速上涨。",
        "COW risk comes from write volume and page coverage; hot keys and large objects can raise copied pages quickly.",
        {
          parent: tx("SET hot:user:42", "SET hot:user:42"),
          pages: tx("Page B 触发写保护缺页", "Page B triggers write-protection fault"),
          cow: tx("等待复制 Page B", "waiting to copy Page B"),
          metrics: tx("latency event: fork", "latency event: fork"),
        },
        "warning",
      ),
      step(
        "复制脏页",
        "Copy dirty pages",
        "为父进程分配新物理页",
        "Allocate a new physical page for parent",
        "pages",
        "cow",
        "Copy-on-Write",
        "Copy-on-Write",
        "内核复制被写入的旧页，父进程改写新页，子进程继续读取 fork 时刻的旧页，因此快照保持一致。",
        "The kernel copies the old written page, the parent modifies the new page, and the child keeps reading the old fork-time page, preserving snapshot consistency.",
        "额外 RSS 随复制页增长；内存余量不足会让后台任务失败或触发系统级风险。",
        "Extra RSS grows with copied pages; weak memory headroom can fail the background job or create system-level risk.",
        {
          pages: tx("Page B 分裂为 old/new", "Page B splits into old/new"),
          cow: tx("COW +640MB", "COW +640MB"),
          child: tx("仍读取旧 Page B", "still reads old Page B"),
          metrics: tx("used_memory_rss 上升", "used_memory_rss rising"),
        },
        "danger",
      ),
      step(
        "后台写入完成",
        "Background write completes",
        "释放快照并验收指标",
        "Release snapshot and verify metrics",
        "writer",
        "metrics",
        "RSS returns",
        "RSS returns",
        "子进程把 RDB、AOF 基础文件或全量同步数据写完后退出，共享页引用释放，COW 额外页随之回落。",
        "After the child finishes writing RDB, AOF base, or full-sync data, it exits, shared-page references are released, and COW extra pages recede.",
        "验收看 latest_fork_usec、rdb/aof 状态、used_memory_rss、mem_fragmentation_ratio 和 latency 事件。",
        "Verification checks latest_fork_usec, rdb/aof status, used_memory_rss, mem_fragmentation_ratio, and latency events.",
        {
          child: tx("子进程退出", "child exited"),
          writer: tx("RDB/AOF/full sync 完成", "RDB/AOF/full sync complete"),
          cow: tx("COW 页释放", "COW pages released"),
          metrics: tx("RSS 回落，status=ok", "RSS recedes, status=ok"),
        },
        "success",
      ),
    ],
    [
      tx("latest_fork_usec", "latest_fork_usec"),
      tx("COW 额外页", "COW extra pages"),
      tx("used_memory_rss", "used_memory_rss"),
      tx("latency event", "latency event"),
      tx("background status", "background status"),
    ],
  );
}

