function k8sTaintToleration(point: GraphKnowledgePoint) {
  const actors = [
    actor("node", "带污点 Node", "Tainted Node", "保存 key、value、effect 和节点状态", "Stores key, value, effect, and node condition", "server"),
    actor("pod", "Pod tolerations", "Pod tolerations", "声明 operator、effect 和 tolerationSeconds", "Declares operator, effect, and tolerationSeconds", "container"),
    actor("filter", "TaintToleration Filter", "TaintToleration Filter", "调度阶段判定 Pod 是否能进入节点", "Decides whether the Pod can enter the node during scheduling", "security"),
    actor("eviction", "NoExecute 驱逐", "NoExecute eviction", "节点异常时按容忍秒数执行驱逐", "Evicts by toleration seconds during node failure", "cluster"),
    actor("events", "事件与验收", "Events and validation", "串联 FailedScheduling、taint 和 Pod 状态", "Correlates FailedScheduling, taints, and Pod status", "data"),
  ];

  return makeSimulation(
    "kubernetes",
    point,
    tx("污点与容忍调度状态模型", "taint and toleration scheduling state model"),
    tx(
      "把 Node taint、Pod toleration、NoSchedule 过滤、NoExecute 驱逐和事件证据放在同一个排障画布中。",
      "Place Node taints, Pod tolerations, NoSchedule filtering, NoExecute eviction, and event evidence on one troubleshooting canvas.",
    ),
    actors,
    {
      node: tx("node-gpu 无污点", "node-gpu has no taint"),
      pod: tx("checkout Pod 无容忍", "checkout Pod has no toleration"),
      filter: tx("等待调度检查", "Awaiting scheduling check"),
      eviction: tx("驱逐控制器空闲", "Eviction controller idle"),
      events: tx("等待事件", "Awaiting events"),
    },
    [
      step(
        "给节点加污点",
        "Taint node",
        "标记专用节点或异常节点",
        "Mark dedicated or unhealthy node",
        "node",
        "filter",
        "dedicated=gpu:NoSchedule",
        "dedicated=gpu:NoSchedule",
        "管理员给节点添加 taint，调度器后续会把普通 Pod 从该节点候选集中移除。",
        "An administrator adds a taint to the node, and the scheduler removes ordinary Pods from that node candidate set.",
        "污点是节点侧的排斥规则，核心字段是 key、value、effect。",
        "A taint is a node-side repulsion rule; the key fields are key, value, and effect.",
        { node: tx("dedicated=gpu:NoSchedule", "dedicated=gpu:NoSchedule"), filter: tx("等待 Pod 约束", "Awaiting Pod constraints") },
      ),
      step(
        "声明 Pod 容忍",
        "Declare toleration",
        "在 Pod spec 写入匹配条件",
        "Write matching condition into Pod spec",
        "pod",
        "filter",
        "operator=Equal / effect=NoSchedule",
        "operator=Equal / effect=NoSchedule",
        "Pod 通过 tolerations 声明能接受哪些 taint；Equal 精确匹配 key/value，Exists 只看 key 和 effect。",
        "The Pod uses tolerations to declare accepted taints; Equal matches key/value exactly, while Exists matches key and effect.",
        "容忍只允许进入被 taint 的节点，节点亲和性和资源检查仍然继续生效。",
        "A toleration only permits entry to a tainted node; node affinity and resource checks still apply.",
        { pod: tx("tolerates dedicated=gpu", "tolerates dedicated=gpu"), filter: tx("匹配规则就绪", "Matching rule ready") },
        "teal",
      ),
      step(
        "Filter 判定调度",
        "Filter scheduling",
        "区分 NoSchedule 与 PreferNoSchedule",
        "Separate NoSchedule from PreferNoSchedule",
        "filter",
        "node",
        "1 pod allowed / 1 pod rejected",
        "1 pod allowed / 1 pod rejected",
        "TaintToleration Filter 对每个候选节点检查 Pod 容忍；缺少 NoSchedule 容忍的 Pod 会留下 FailedScheduling 事件。",
        "The TaintToleration Filter checks Pod tolerations for each candidate node; a Pod missing NoSchedule toleration leaves a FailedScheduling event.",
        "Pending 排障要把 `kubectl describe pod` 事件和节点 taint 列表放在一起读。",
        "Pending triage reads `kubectl describe pod` events together with the node taint list.",
        { filter: tx("gpu-job allowed / checkout rejected", "gpu-job allowed / checkout rejected"), events: tx("FailedScheduling x3", "FailedScheduling x3") },
        "warning",
      ),
      step(
        "NoExecute 驱逐",
        "NoExecute eviction",
        "节点异常触发限时容忍",
        "Node failure starts timed toleration",
        "node",
        "eviction",
        "node.kubernetes.io/unreachable:NoExecute",
        "node.kubernetes.io/unreachable:NoExecute",
        "节点控制器会为不可达或未就绪节点添加 NoExecute taint；Pod 没有容忍会立即被驱逐，有 tolerationSeconds 会等待到期。",
        "The node controller adds NoExecute taints for unreachable or not-ready nodes; Pods without toleration are evicted immediately, and tolerationSeconds delays eviction.",
        "NoExecute 负责运行中 Pod 的去留，适合观察节点故障切换和业务恢复时间。",
        "NoExecute governs whether running Pods stay, making it useful for node failover and recovery-time analysis.",
        { node: tx("unreachable:NoExecute", "unreachable:NoExecute"), eviction: tx("tolerationSeconds=300", "tolerationSeconds=300") },
        "danger",
      ),
      step(
        "验证事件链",
        "Validate event chain",
        "对齐 node、pod、events 和恢复结果",
        "Align node, pod, events, and recovery result",
        "events",
        "pod",
        "describe + get node -o wide",
        "describe + get node -o wide",
        "验收时同时确认节点 taint、Pod tolerations、FailedScheduling 或 Killing 事件、重新调度位置和业务 Ready 状态。",
        "Validation checks node taints, Pod tolerations, FailedScheduling or Killing events, rescheduled placement, and business Ready state together.",
        "稳定配置通常把专用节点隔离、系统 DaemonSet 容忍和故障驱逐策略拆成独立规则。",
        "Stable setups keep dedicated-node isolation, system DaemonSet tolerations, and failure-eviction policy as separate rules.",
        {
          events: tx("events explain placement", "events explain placement"),
          pod: tx("gpu-job Scheduled=True", "gpu-job Scheduled=True"),
          eviction: tx("pod rescheduled to node-b", "pod rescheduled to node-b"),
        },
        "success",
      ),
    ],
    [
      tx("NoSchedule", "NoSchedule"),
      tx("NoExecute", "NoExecute"),
      tx("tolerationSeconds", "tolerationSeconds"),
      tx("TaintToleration Filter", "TaintToleration Filter"),
      tx("FailedScheduling Events", "FailedScheduling Events"),
    ],
  );
}

function k8sPodAffinity(point: GraphKnowledgePoint) {
  const actors = [
    actor("workload", "待调度 Pod", "Pending Pod", "带有 affinity / antiAffinity 规则的新 Pod", "New Pod carrying affinity / antiAffinity rules", "container"),
    actor("selector", "labelSelector", "labelSelector", "匹配已有 Pod 标签并得到目标集合", "Matches existing Pod labels and builds the target set", "data"),
    actor("domains", "topologyKey 域", "topologyKey domains", "按节点、可用区或机架归并匹配 Pod", "Groups matching Pods by node, zone, or rack", "cluster"),
    actor("filter", "InterPodAffinity Filter", "InterPodAffinity Filter", "硬规则决定节点是否可行", "Hard rules decide whether a node is feasible", "security"),
    actor("score", "Affinity Score", "Affinity score", "软规则把更接近目标 Pod 的节点排前", "Soft rules rank nodes closer to target Pods higher", "cpu"),
  ];

  return makeSimulation(
    "kubernetes",
    point,
    tx("Pod 亲和性调度状态模型", "pod affinity scheduler state model"),
    tx(
      "把 labelSelector、topologyKey、PodAffinity、PodAntiAffinity、Filter/Score 和 FailedScheduling 事件放在同一个调度画布中。",
      "Place labelSelector, topologyKey, PodAffinity, PodAntiAffinity, Filter/Score, and FailedScheduling events on one scheduling canvas.",
    ),
    actors,
    {
      workload: tx("frontend-v2 Pending", "frontend-v2 Pending"),
      selector: tx("等待 selector", "Awaiting selector"),
      domains: tx("zone-a has backend", "zone-a has backend"),
      filter: tx("等待 InterPodAffinity", "Awaiting InterPodAffinity"),
      score: tx("未选择节点", "No node selected"),
    },
    [
      step(
        "读取亲和规则",
        "Read affinity rules",
        "加载 PodAffinity 与 AntiAffinity",
        "Load PodAffinity and AntiAffinity",
        "workload",
        "selector",
        "app=backend / topologyKey=zone",
        "app=backend / topologyKey=zone",
        "调度器读取 Pod spec 中的 `podAffinity` 与 `podAntiAffinity`，把 required 交给 Filter，把 preferred 交给 Score。",
        "The scheduler reads podAffinity and podAntiAffinity from the Pod spec, sending required terms to Filter and preferred terms to Score.",
        "先确认 rule 作用域、label selector 和 topologyKey，避免把规则写成全局约束。",
        "Start with rule scope, label selector, and topologyKey so the rule targets the intended domain.",
        { workload: tx("frontend-v2 has affinity", "frontend-v2 has affinity"), selector: tx("selector app=backend", "selector app=backend") },
      ),
      step(
        "匹配已有 Pod",
        "Match existing Pods",
        "用 selector 找到参照 Pod",
        "Find reference Pods with selector",
        "selector",
        "domains",
        "backend Pods in zone-a/zone-b",
        "backend Pods in zone-a/zone-b",
        "InterPodAffinity 先遍历已有 Pod，按 label selector 取出参照集合，再把这些 Pod 所在节点的 topologyKey 值作为候选域。",
        "InterPodAffinity scans existing Pods, selects references by label selector, then uses their nodes' topologyKey values as candidate domains.",
        "selector 命中为空时，required 规则通常会让 Pod 保持 Pending。",
        "An empty selector match commonly leaves a required-affinity Pod Pending.",
        { selector: tx("backend set=3 Pods", "backend set=3 Pods"), domains: tx("zone-a, zone-b contain backend", "zone-a, zone-b contain backend") },
        "teal",
      ),
      step(
        "执行硬规则过滤",
        "Apply hard rules",
        "requiredDuringScheduling 过滤节点",
        "Filter nodes with requiredDuringScheduling",
        "domains",
        "filter",
        "zone-c rejected",
        "zone-c rejected",
        "requiredDuringScheduling 要求新 Pod 落入已有匹配 Pod 所在的拓扑域；反亲和规则会把包含冲突 Pod 的域从候选集中移除。",
        "requiredDuringScheduling requires the new Pod to land in a topology domain containing matching Pods, while anti-affinity removes domains containing conflicting Pods.",
        "Pending 事件要同时读 `InterPodAffinity`、目标 label 和候选节点的 topologyKey 标签。",
        "Pending events should be read with InterPodAffinity, target labels, and topologyKey labels on candidate nodes.",
        { filter: tx("node-c rejected / node-a feasible", "node-c rejected / node-a feasible"), domains: tx("zone-c lacks backend", "zone-c lacks backend") },
        "warning",
      ),
      step(
        "执行软规则打分",
        "Score preferred rules",
        "preferredDuringScheduling 排序候选节点",
        "Rank candidates with preferredDuringScheduling",
        "filter",
        "score",
        "node-a score=92",
        "node-a score=92",
        "preferredDuringScheduling 会按 weight 给靠近目标 Pod 或远离冲突 Pod 的节点加分，并与资源、拓扑分布等其他 Score 插件合并。",
        "preferredDuringScheduling adds weighted scores for nodes near target Pods or away from conflicting Pods, then combines them with resource and spread scores.",
        "软规则适合表达偏好，适合和拓扑分布约束共同治理副本位置。",
        "Soft rules express preference and pair well with topology spread for placement governance.",
        { score: tx("node-a +92 / node-b +74", "node-a +92 / node-b +74"), filter: tx("feasible nodes scored", "feasible nodes scored") },
        "success",
      ),
      step(
        "绑定并验收",
        "Bind and validate",
        "核对节点位置与事件",
        "Check node placement and events",
        "score",
        "workload",
        "Bound node-a / zone-a",
        "Bound node-a / zone-a",
        "调度器把 Pod 绑定到满足硬规则且得分最高的节点；验收时同时看 Pod Events、`spec.nodeName`、节点标签和匹配 Pod 分布。",
        "The scheduler binds the Pod to the highest-scoring feasible node; validation reads Pod Events, spec.nodeName, node labels, and matching Pod placement together.",
        "生产中把服务就近、跨节点分散和故障域隔离拆成可审计的独立规则。",
        "Production setups keep service colocation, cross-node separation, and failure-domain isolation as auditable placement rules.",
        {
          workload: tx("frontend-v2 Running on node-a", "frontend-v2 Running on node-a"),
          domains: tx("colocated with backend", "colocated with backend"),
          score: tx("Scheduled=True", "Scheduled=True"),
        },
        "brand",
      ),
    ],
    [
      tx("labelSelector", "labelSelector"),
      tx("topologyKey", "topologyKey"),
      tx("PodAffinity", "PodAffinity"),
      tx("PodAntiAffinity", "PodAntiAffinity"),
      tx("FailedScheduling Events", "FailedScheduling Events"),
    ],
  );
}

