          "Port publishing creates a host IP:port entry and uses Docker NAT/filter rules to forward traffic to the container port.",
          "外部访问失败时同时查 published port、服务监听 0.0.0.0、DOCKER-USER 和防火墙。",
          "For failed external access, check published port, service listen on 0.0.0.0, DOCKER-USER, and firewall together.",
