          "核对排障信号",
          "Check debug signals",
          "ps / port / inspect / ss",
          "ps / port / inspect / ss",
          "app",
          "debug",
          "EXPOSE + Ports + listen",
          "EXPOSE + Ports + listen",
          "把镜像 EXPOSE、实际 publish、容器内监听和防火墙策略放在同一张表里核对。",
